-- =====================================================================
-- CardioEMR  migration 0003_cad_dictionary_api   (2026-11-22)
--   1. CAD data dictionary v1: variable definitions and protocol
--      variables for CEMR-CAD v1 (generated by tools/generate_dictionaries.py).
--   2. Oral anticoagulants in the drug catalogue (CAD on_oac variable).
--   3. Stable error tags for the registry API: every rule raised by a
--      trigger carries HINT 'cemr:<CODE>'; constraint names that the API
--      maps are given stable names; ref.api_error_map lists both.
--   4. Assessment lock and unlock rules: lock by coordinator or PI when
--      complete and free of open queries; unlock by PI with a reason.
-- =====================================================================
SET check_function_bodies = off;

-- 2. Oral anticoagulants ----------------------------------------------
SELECT drug_id, 'ANTICOAGULANT' FROM ref.drugs
 WHERE drug_code IN ('WARFARIN','ACENOCOUMAROL','APIXABAN','RIVAROXABAN','DABIGATRAN','EDOXABAN');

-- 3. Stable constraint names the API maps ------------------------------
ALTER TABLE registry.enrolments RENAME CONSTRAINT enrolments_check TO enrolments_enrolled_requires_eligibility;
ALTER TABLE registry.enrolments RENAME CONSTRAINT enrolments_check1 TO enrolments_closed_requires_date;
ALTER TABLE registry.assessments RENAME CONSTRAINT assessments_check TO assessments_missed_requires_reason;
ALTER TABLE research.export_jobs RENAME CONSTRAINT export_jobs_check TO export_jobs_approved_requires_approver;
ALTER TABLE research.export_jobs RENAME CONSTRAINT export_jobs_check1 TO export_jobs_four_eyes;

-- One table the API reads at start-up to translate database errors.
CREATE TABLE ref.api_error_map (
  source_kind  text NOT NULL CHECK (source_kind IN ('hint','constraint')),
  source_name  text NOT NULL,                  -- 'cemr:CONSENT_REQUIRED' or a constraint / index name
  error_code   text NOT NULL CHECK (error_code ~ '^[A-Z_]+$'),
  http_status  smallint NOT NULL CHECK (http_status BETWEEN 400 AND 599),
  title        text NOT NULL,
  PRIMARY KEY (source_kind, source_name)
);
GRANT SELECT ON ref.api_error_map TO r_assistant, r_nurse, r_clinician, r_research_coordinator,
  r_principal_investigator, r_centre_admin, r_platform_admin;

-- 3b. Error tags on trigger rules (bodies as in 0001/0002, HINT added) ----
CREATE OR REPLACE FUNCTION registry.enrolment_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, registry, clinical AS $$
DECLARE v_requires boolean; v_type uuid; c record;
BEGIN
  SELECT requires_research_consent, registry_type_id INTO v_requires, v_type
    FROM registry.registry_protocols WHERE protocol_id = NEW.protocol_id;
  IF v_type <> NEW.registry_type_id THEN
    RAISE EXCEPTION 'protocol belongs to a different registry' USING ERRCODE = 'check_violation', HINT = 'cemr:PROTOCOL_MISMATCH';
  END IF;
  IF NEW.enrolment_status = 'enrolled' AND (TG_OP = 'INSERT' OR OLD.enrolment_status <> 'enrolled') THEN
    IF NOT EXISTS (SELECT 1 FROM registry.protocol_sites
                   WHERE protocol_id = NEW.protocol_id AND centre_id = NEW.centre_id AND site_status = 'active') THEN
      RAISE EXCEPTION 'protocol is not active at this centre' USING ERRCODE = 'check_violation', HINT = 'cemr:SITE_NOT_ACTIVE';
    END IF;
    IF v_requires THEN
      SELECT * INTO c FROM clinical.patient_consents WHERE consent_id = NEW.consent_id;
      IF c IS NULL OR c.patient_id <> NEW.patient_id OR c.consent_type <> 'research_registry'
         OR c.protocol_id <> NEW.protocol_id OR c.consent_status <> 'active' THEN
        RAISE EXCEPTION 'enrolment requires an active research consent for this protocol'
          USING ERRCODE = 'check_violation', HINT = 'cemr:CONSENT_REQUIRED';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION registry.assessment_window() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE e record; v record;
BEGIN
  SELECT * INTO e FROM registry.enrolments WHERE enrolment_id = NEW.enrolment_id;
  NEW.days_from_index := NEW.assessment_date - e.index_date;
  SELECT * INTO v FROM registry.visit_schedule WHERE protocol_id = e.protocol_id AND visit_code = NEW.visit_code;
  IF v IS NULL THEN
    NEW.within_window := NULL;
  ELSE
    NEW.within_window := NEW.days_from_index BETWEEN v.target_day - v.window_before_days
                                                 AND v.target_day + v.window_after_days;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.locked_at IS NOT NULL AND NEW.locked_at IS NOT NULL
     AND (to_jsonb(NEW) - 'patient_id' - 'updated_at' - 'updated_by' - 'row_version')
         <> (to_jsonb(OLD) - 'patient_id' - 'updated_at' - 'updated_by' - 'row_version') THEN
    RAISE EXCEPTION 'assessment is locked' USING ERRCODE = 'insufficient_privilege', HINT = 'cemr:ASSESSMENT_LOCKED';
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION registry.variable_value_validate() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE d record;
BEGIN
  SELECT * INTO d FROM registry.variable_definitions WHERE variable_id = NEW.variable_id;
  IF NEW.value_status <> 'present' THEN RETURN NEW; END IF;
  IF (d.data_type IN ('numeric','integer') AND NEW.numeric_value IS NULL)
  OR (d.data_type = 'text' AND NEW.text_value IS NULL)
  OR (d.data_type = 'date' AND NEW.date_value IS NULL)
  OR (d.data_type = 'boolean' AND NEW.boolean_value IS NULL)
  OR (d.data_type = 'coded' AND NEW.coded_value IS NULL)
  OR (d.data_type = 'multi_coded' AND NEW.coded_values IS NULL) THEN
    RAISE EXCEPTION 'variable % expects a % value', d.variable_code, d.data_type USING ERRCODE = 'check_violation', HINT = 'cemr:WRONG_VALUE_TYPE';
  END IF;
  IF d.data_type = 'integer' AND NEW.numeric_value <> trunc(NEW.numeric_value) THEN
    RAISE EXCEPTION 'variable % expects an integer', d.variable_code USING ERRCODE = 'check_violation', HINT = 'cemr:WRONG_VALUE_TYPE';
  END IF;
  IF NEW.numeric_value < d.min_value OR NEW.numeric_value > d.max_value THEN
    RAISE EXCEPTION 'variable % value % outside % to %', d.variable_code, NEW.numeric_value, d.min_value, d.max_value
      USING ERRCODE = 'check_violation', HINT = 'cemr:VALUE_OUT_OF_RANGE';
  END IF;
  IF d.data_type = 'coded' AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(d.allowed_values) a WHERE a->>'code' = NEW.coded_value) THEN
    RAISE EXCEPTION 'variable % does not allow code %', d.variable_code, NEW.coded_value USING ERRCODE = 'check_violation', HINT = 'cemr:CODE_NOT_ALLOWED';
  END IF;
  IF d.data_type = 'multi_coded' AND EXISTS (
       SELECT 1 FROM unnest(NEW.coded_values) v
       WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(d.allowed_values) a WHERE a->>'code' = v)) THEN
    RAISE EXCEPTION 'variable % has a code outside its allowed values', d.variable_code USING ERRCODE = 'check_violation', HINT = 'cemr:CODE_NOT_ALLOWED';
  END IF;
  IF EXISTS (SELECT 1 FROM registry.assessments WHERE assessment_id = NEW.assessment_id AND locked_at IS NOT NULL) THEN
    RAISE EXCEPTION 'assessment is locked' USING ERRCODE = 'insufficient_privilege', HINT = 'cemr:ASSESSMENT_LOCKED';
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION registry.lipid_attainment_fill() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  SELECT ldl_target_mg_dl INTO NEW.ldl_target_mg_dl FROM ref.ldl_target_rules
   WHERE rule_set_id = NEW.rule_set_id AND risk_category = NEW.risk_category;
  IF NEW.ldl_target_mg_dl IS NULL THEN
    RAISE EXCEPTION 'risk category % is not defined in this guideline rule set', NEW.risk_category
      USING ERRCODE = 'foreign_key_violation', HINT = 'cemr:RISK_CATEGORY_UNKNOWN';
  END IF;
  NEW.target_met := registry.ldl_target_met(NEW.rule_set_id, NEW.risk_category, NEW.ldl_mg_dl, NEW.ldl_pct_reduction);
  NEW.calculated_at := now();
  RETURN NEW;
END $$;

-- 4. Lock and unlock rules -------------------------------------------
-- Lock: research coordinator or PI; assessment complete, missed or not
-- applicable; no value under query.  Unlock: PI only, with a change reason.
-- Roles outside the r_* application roles (migrations, the owner) are not checked.
CREATE OR REPLACE FUNCTION registry.assessment_lock_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE v_role text := app.current_app_role();
BEGIN
  IF OLD.locked_at IS NULL AND NEW.locked_at IS NOT NULL THEN
    IF v_role IS NOT NULL AND v_role NOT IN ('research_coordinator','principal_investigator') THEN
      RAISE EXCEPTION 'role % may not lock assessments', v_role
        USING ERRCODE = 'insufficient_privilege', HINT = 'cemr:LOCK_ROLE';
    END IF;
    IF NEW.completion_status = 'partial' THEN
      RAISE EXCEPTION 'assessment is still partial' USING ERRCODE = 'check_violation', HINT = 'cemr:ASSESSMENT_INCOMPLETE';
    END IF;
    IF EXISTS (SELECT 1 FROM registry.variable_values
               WHERE assessment_id = NEW.assessment_id AND verification_status = 'queried') THEN
      RAISE EXCEPTION 'assessment has open data queries' USING ERRCODE = 'check_violation', HINT = 'cemr:OPEN_QUERIES';
    END IF;
    NEW.locked_by := coalesce(NEW.locked_by, app.current_user_id());
  ELSIF OLD.locked_at IS NOT NULL AND NEW.locked_at IS NULL THEN
    IF v_role IS NOT NULL AND v_role <> 'principal_investigator' THEN
      RAISE EXCEPTION 'role % may not unlock assessments', v_role
        USING ERRCODE = 'insufficient_privilege', HINT = 'cemr:LOCK_ROLE';
    END IF;
    IF app.change_reason() IS NULL THEN
      RAISE EXCEPTION 'unlocking needs a change reason' USING ERRCODE = 'check_violation', HINT = 'cemr:CHANGE_REASON_REQUIRED';
    END IF;
    NEW.locked_by := NULL;
  END IF;
  RETURN NEW;
END $$;
-- Named to fire before assessments_window, which blocks edits to a locked row.
CREATE TRIGGER assessments_a_lock_guard BEFORE UPDATE OF locked_at ON registry.assessments
  FOR EACH ROW EXECUTE FUNCTION registry.assessment_lock_guard();

